605	func (host *pclLanguageHost) GenerateProgram(
606		ctx context.Context, req *pulumirpc.GenerateProgramRequest,
607	) (*pulumirpc.GenerateProgramResponse, error) {
608		loader, err := schema.NewLoaderClient(req.LoaderTarget)
609		if err != nil {
610			return nil, err
611		}
612		defer loader.Close()
613	
614		parser := hclsyntax.NewParser()
615		for path, contents := range req.Source {
616			if err = parser.ParseFile(strings.NewReader(contents), path); err != nil {
617				return nil, err
618			}
619			if parser.Diagnostics.HasErrors() {
620				return nil, parser.Diagnostics
621			}
622		}
623	
624		options := []pcl.BindOption{
625			pcl.Loader(schema.NewCachedLoader(loader)),
626			pcl.PreferOutputVersionedInvokes,
627		}
628		if !req.Strict {
629			options = append(options, pcl.NonStrictBindOptions()...)
630		}
631	
632		program, diags, err := pcl.BindProgram(parser.Files, options...)
633		if err != nil {
634			return nil, err
635		}
636	
637		rpcDiagnostics := plugin.HclDiagnosticsToRPCDiagnostics(diags)
638		if diags.HasErrors() {
639			return &pulumirpc.GenerateProgramResponse{Diagnostics: rpcDiagnostics}, nil
640		}
641		if program == nil {
642			return nil, errors.New("internal error program was nil")
643		}
644	
645		convertedSource := make(map[string][]byte, len(req.Source))
646		for filename, contents := range req.Source {
647			convertedSource[filename] = []byte(contents)
648		}
649	
650		return &pulumirpc.GenerateProgramResponse{
651			Source:      convertedSource,
652			Diagnostics: rpcDiagnostics,
653		}, nil
654	}
